import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate issueDate format and real date
  const dateResult = validateDate(issueDate);
  if (!dateResult.ok) return dateResult;

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Get product and validate SKU
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line: qty times unitPrice.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
 * @returns {{ subtotal: number, total: number }} Both in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  return {
    subtotal,
    total: subtotal,
  };
}

/**
 * Add a line to an invoice (or increase qty if SKU already exists).
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number }} item
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Get product and validate SKU
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Create new lines array with the line added or updated
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingIndex >= 0) {
    // Update existing line
    newLines[existingIndex] = {
      ...newLines[existingIndex],
      qty: newLines[existingIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const index = invoice.lines.findIndex((line) => line.sku === sku);

  if (index === -1) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

function validateDate(dateStr) {
  if (typeof dateStr !== 'string') return fail('DATE_INVALID');

  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateStr);
  if (!match) return fail('DATE_INVALID');

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  // Check if it's a valid date
  const date = new Date(year, month - 1, day);
  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day
  ) {
    return fail('DATE_INVALID');
  }

  return ok(dateStr);
}

